// === GRID BFS (4-DIRECTIONAL) ===
const dirs = [[0,1],[0,-1],[1,0],[-1,0]];

function gridBFS(grid, startR, startC) {
  const m = grid.length, n = grid[0].length;
  const visited = Array.from({length: m}, () => new Array(n).fill(false));
  const queue = [[startR, startC]];
  visited[startR][startC] = true;

  while (queue.length) {
    const [r, c] = queue.shift();
    // process cell (r, c) here
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      // boundary check + unvisited check
      if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc]) {
        visited[nr][nc] = true; // mark before enqueue, not after dequeue
        queue.push([nr, nc]);
      }
    }
  }
}

// === 2D PREFIX SUM ===
function build2DPrefix(matrix) {
  const m = matrix.length, n = matrix[0].length;
  const pre = Array.from({length: m+1}, () => new Array(n+1).fill(0));
  for (let i = 1; i <= m; i++)
    for (let j = 1; j <= n; j++)
      pre[i][j] = matrix[i-1][j-1] + pre[i-1][j] + pre[i][j-1] - pre[i-1][j-1];
  return pre;
}
// Rectangle sum (r1,c1) to (r2,c2) inclusive, 0-indexed:
// pre[r2+1][c2+1] - pre[r1][c2+1] - pre[r2+1][c1] + pre[r1][c1]
